import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.CeXt7FPx.js";const f=JSON.parse('{"title":"Moving from Herd or Valet","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migrating.md","filePath":"guide/migrating.md"}'),o={name:"guide/migrating.md"};function n(r,e,d,h,l,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="moving-from-herd-or-valet" tabindex="-1">Moving from Herd or Valet <a class="header-anchor" href="#moving-from-herd-or-valet" aria-label="Permalink to &quot;Moving from Herd or Valet&quot;">​</a></h1><p>Tiffin can bring your Laravel Herd or Laravel Valet sites over in one command. It reads their configuration, shows what it would do, asks, and then does it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> herd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # show the plan and stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> herd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # show the plan, ask, apply</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> valet</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # do not ask</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> herd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # for scripts</span></span></code></pre></div><h2 id="what-comes-over" tabindex="-1">What comes over <a class="header-anchor" href="#what-comes-over" aria-label="Permalink to &quot;What comes over&quot;">​</a></h2><table tabindex="0"><thead><tr><th>From</th><th>To Tiffin</th></tr></thead><tbody><tr><td>Parked folders</td><td>parked, so every folder inside is a site</td></tr><tr><td>Linked sites</td><td>linked under the same name</td></tr><tr><td>Secured sites</td><td>HTTPS turned on (Tiffin makes its own certificates)</td></tr><tr><td>A site&#39;s own PHP version</td><td>the site pinned to that version</td></tr><tr><td><code>herd.yml</code> (Herd only)</td><td>a <code>tiffin.toml</code> in the project</td></tr></tbody></table><p>For <code>herd.yml</code>, <code>php</code> becomes <code>[runtimes] php</code>, <code>secured</code> becomes <code>[site] https</code>, <code>aliases</code> and <code>name</code> go to <code>[site]</code>, <code>services</code> go to <code>[services]</code> (with version and port) and <code>workspaces</code> become <code>[workspaces]</code> (see <a href="/tiffin/guide/projects">Projects: tiffin up</a>). Anything Tiffin has no equivalent for is listed as a warning and left out.</p><p>Workspace hooks are run without a shell in Tiffin. A Herd hook such as <code>npm ci &amp;&amp; npm run build</code> is dropped with a warning: put the steps in a script and call that. If a workspace clones the database, Tiffin needs a database name under <code>[services]</code>; it uses the folder&#39;s name for the first database service and tells you so in the plan.</p><h2 id="it-only-reads" tabindex="-1">It only reads <a class="header-anchor" href="#it-only-reads" aria-label="Permalink to &quot;It only reads&quot;">​</a></h2><p>Tiffin never edits, moves or deletes Herd&#39;s or Valet&#39;s files. It does not touch their certificates, DNS settings or the hosts file, and it runs no commands or shell. What it writes is Tiffin&#39;s own: parked folders, linked sites, HTTPS, PHP versions and <code>tiffin.toml</code>. Whatever it cannot find is reported, not an error.</p><p>If a project already has a <code>tiffin.toml</code>, it is not merged. The plan shows what differs and leaves the file alone; add <code>--force</code> to replace it.</p><h2 id="php-versions" tabindex="-1">PHP versions <a class="header-anchor" href="#php-versions" aria-label="Permalink to &quot;PHP versions&quot;">​</a></h2><p>A PHP version Tiffin does not have is marked &quot;not installed&quot; in the plan. Add <code>--install-php</code> to install it while importing; otherwise the site keeps the default PHP and the plan names the command to run (<code>tiffin add php 8.3</code>). The <code>tiffin.toml</code> still carries the version, so <code>tiffin up</code> installs it later.</p><h2 id="in-the-app" tabindex="-1">In the app <a class="header-anchor" href="#in-the-app" aria-label="Permalink to &quot;In the app&quot;">​</a></h2><p>The first time the app opens after setup and finds Herd or Valet, it offers to import: a dialog lists the plan, with a checkbox to install missing PHP versions and one to replace <code>tiffin.toml</code> files that exist. <strong>Apply</strong> runs it and shows each step. <strong>Not now</strong> closes it and the app does not ask again; the command above still works.</p><p>Run it again at any time: what is already there is reported as such and nothing is changed twice.</p>`,15)])])}const k=t(o,[["render",n]]);export{f as __pageData,k as default};
